INSERT INTO `sticky_notes` (`id`, `title`, `text`, `note_index`, `sticker_color`, `text_color`) VALUES
(6, NULL, 'CONTACTS\n\nInovie Lab : 81930018\n\nBeirut Pet Hospital\nCLINIC + WHISH: 03003625\n\nLebanese Veterinary Referrals: 81515145\n\nLe Veto - Tabaris: 01325355\nLe Veto - Whatsapp: 03840810\nLe Veto (Aleen): 70998227\n\nTannourine Driver (Marwan): 70257966\n\nBlue Tails Shelter/Hotel(Karantina): 03333435\n\nMohammad Itani (all airport papers): 71198140\n\n? Issam Hijazi (Turkey MEA): 03071091 \n\n?? Kassem Alloush : 03231663 ??\n\n?? Farouk (Nissan امن داخلي): 76747665 ??', 1, '#1d4ed8', '#ffffff'),
(7, NULL, 'CLIENT REQUESTS\n\n- Mohammad Arnaout: pill pocket for cats (03102100)\n-Mohammaf Alawiyeh 03887651 small water fountain\n-Mona hneineh: Webbox treat for cats (03732915)\n- Youssef Ossaile: audio + video treat dispenser\n- Nisrine Jaafar: stainless litter box\n- Ali Hammoud: Royal Canin Light\n- Hasan Kanber: Pellets (not meusli) for rabbits (81917026)\n\n- Lena Kiwan: Voopet dog shoes size 5 \n- Sana Fanous: \n1. Large Dress (Bichon)\n2. Medium T-shirt (Poodle)\n3. Small T-shirt (Yorkshire)\n4. Medium Dress (Yorkshire)\n5. Small Dress (Chiuahua)\n6. Dress size 5 (Hotdog Poodle Mix; short legs)\n7. Majd Yassine (Name tag for cat)', 5, '#f97316', '#ffffff'),
(9, NULL, 'WHISH\n\n- Lena Ismail: $33 (sent)\n- Tahani Saadeh: 85$+26$= 111$ sent\n- Nadide Ajam 15$ (21 july)\n- wajd jassam: $25.5 (not yet sent) \n- Rami Zawawi: $50 (12 aug)\n-Mohammad Fares: 20 (sent and paid the 0.5 by cash)', 6, '#b91c1c', '#ffffff'),
(11, NULL, 'TO ORDER\n\nREVOLUTION (24 pcs for Roxane Hmede)\nZYLEXIS\n\nTofu Litter\nProPlan\nNexGuard\n\nMEPC\n- Stainless bowls (colored bottom) + G01\n- Hay\n- Wood Fibre\n- Sepia Shell\n- Catnip Spray\n\nMEDIVET\n- Regular + Sensor Fountains\n- Stainless Litter Boxes\n- Accessories\n- Automatic Litter Boxes', 4, '#fdba74', '#ffffff'),
(12, NULL, 'TODAY\n\n- Lena Ismail - Call for outstanding payment \n- Wajd Jassam - 25.5 (sabrine khasfi on 23/7??)\n- Nadine Ajam - 15 (21 July) sent and removed from system?\n\n- Dr. ALI:\nCheck Vaccine Book for:\n-- Joseph Talj - Blackie\n-- Rasha Saadawi - Sasha\n\nNada\n- Tamara Rishwani (return vetsbi) !!!!!\n- Finalize PAWPOTS + get back to Meghery \n- SMART BONES - SEND WHISH ', 0, '#ff0000', '#ffffff'),
(13, NULL, '- Hooks for display\n- Shelves for display \n- Dividers for Binders\n- Whiteboards + Labels for Crates in Wards \n- Stickes + notepads\n\n* Barcode Sticker:\nApli Ref 392 / 1000pcs / 3.6 x 5.3cm / 24.5$', 8, '#fffa75', '#000000'),
(14, NULL, 'SCHEDULES\n\nVET\n- Dr. Ali: Mon-Fri\n- Dr. Mahmoud: Mon - Wed - Fri - Sat\n\nRECEPTION\n- Nour: Mon - Tues - Wed\n- Sacha: Thur - Fri - Sat\n\nGROOMING\n- (In House) Karim: Mon - Fri + Sat (9-1)\n- (GUEST) - Omar: Sat\n\nCLEANING\n- Habib: Tues - Fri (AM) + Sat (PM)', 2, '#3b82f6', '#ffffff'),
(15, NULL, '%%%\n\n- Dr. Ali:\nSurgeries: 30% \nMedical services + Products: (Ask)\n\n- Dr. Mahmoud:\nSurgeries (he will perform them): 50% \nServices: 20-30% \nMedical products: 0-20% (Ask)\n\n- Dr. Rashid\nSurgeries (he will perform them and bring his own equipment): 70% \n\n- Soultan:\nMedical services: 30% \nGrooming: 16%\nMedical products: 0-20% (Ask)\n\n- Guest Groomer: Omar Trad\nAll grooming services: 50%', 3, '#93c5fd', '#ffffff'),
(16, NULL, '81871837 Mira Akl - 5th year vet student (internship)  ', 7, '#93c5fd', '#000000'),
(17, NULL, '- $11.961 Touch - 3/8/26\n- FIRAS: payment for Echo (abdominal+cardiac) for Alaa Khalil at Le Veto: $90 (paid by whish)  - 16/7/26\n- $40 Jaafar for domain\n- GOOGLE ONE: Yearly Subscription: $16.99\n- OGERO: May ($34.67) + June ($34.38)\n- $150 - 30/6/26\n', 9, '#fffa75', '#000000'),
(18, NULL, ' ', 10, '#fffa75', '#000000'),
(19, NULL, ' ', 11, '#fffa75', '#000000');
