INSERT INTO `whatsapp_templates` (`id`, `name`, `message_template`, `location`, `is_active`, `created_at`, `updated_at`) VALUES
(3, 'Due Service Reminder - ENGLISH', 'Hello *{{customer_name}}*!\n\nThis is a friendly reminder that *{{pet_name}}* is due for *{{appointment_type}}* on *{{appointment_datetime}}*.\n\nTo book an appointment, please let us know your preferred day and time, and we will do our best to accommodate you.\n\nThank you, and we look forward to seeing you!', 'reminders', 1, '2026-07-13 13:55:51', '2026-07-13 14:02:32'),
(4, 'Due Service Reminder - ARABIC', 'مرحباً *{{customer_name}}*!\n\nنودّ تذكيرك بأنه سيحين وقت *{{appointment_type}}* لـ *{{pet_name}}* بتاريخ *{{appointment_datetime}}*.\n\nلحجز موعد، يرجى إبلاغنا باليوم والوقت المناسبين لكم، وسنبذل قصارى جهدنا لتلبية طلبكم.\n\nشكراً لكم، ونتطلع إلى استقبالكم!', 'reminders', 1, '2026-07-13 13:56:24', '2026-07-13 16:04:54'),
(5, 'Appointment Reminder - English', 'Hello *{{customer_name}}*!\n\nThis is a friendly reminder that *{{pet_name}}* has an appointment at VET 101 Animal Hospital:\n\n*{{appointment_datetime}}*\n\n*{{appointment_type}}*\n\nThank you, and we look forward to seeing you!', 'reservations', 1, '2026-07-13 16:23:51', '2026-07-13 16:23:51'),
(6, 'Appointment Reminder - ARABIC', 'مرحباً *{{customer_name}}*!\n\nنودّ تذكيرك بأن لدى *{{pet_name}}* موعداً في مستشفى VET 101 للحيوانات:\n\n*{{appointment_datetime}}*\n\n*{{appointment_type}}*\n\nشكراً لكم، ونتطلع إلى استقبالكم!', 'reservations', 1, '2026-07-13 16:24:22', '2026-07-13 16:24:22'),
(7, 'Appointment Confirmation - ENGLISH', 'Hello *{{customer_name}}*!\n\nThis is a friendly reminder that *{{pet_name}}* has an appointment at VET 101 Animal Hospital tomorrow:\n\n*{{appointment_datetime}}*\n\n*{{appointment_type}}*\n\nPlease reply with:\n\n*CONFIRM*\n\nor\n\n*RESCHEDULE* (and let us know your preferred day and time, we\'ll do our best to accommodate you)\n\nThank you, and we look forward to seeing you!', 'reservations', 1, '2026-07-13 16:25:27', '2026-07-13 16:25:27'),
(8, 'Appointment Confirmation - ARABIC', 'مرحباً *{{customer_name}}*!\n\nنودّ تذكيرك بأن لدى *{{pet_name}}* موعداً غداً في مستشفى VET 101 للحيوانات:\n\n*{{appointment_datetime}}*\n\n*{{appointment_type}}*\n\nيرجى الرد بكلمة:\n\n*\"نعم\"* لتأكيد الموعد\n\nأو\n\n*\"لا\"* لإعادة جدولة الموعد (مع إبلاغنا باليوم والوقت المناسبين لكم، وسنبذل قصارى جهدنا لتلبية طلبكم)\n\nشكراً لكم، ونتطلع إلى استقبالكم!', 'reservations', 1, '2026-07-13 16:26:06', '2026-07-13 16:26:06');
